import{_ as i,o as a,c as t,ae as r}from"./chunks/framework.DFTT1zkb.js";const d=JSON.parse('{"title":"入学准备","description":"","frontmatter":{},"headers":[],"relativePath":"begin/preparation.md","filePath":"begin/preparation.md"}'),o={name:"begin/preparation.md"};function u(s,l,e,n,h,c){return a(),t("div",null,[...l[0]||(l[0]=[r('<h1 id="入学准备" tabindex="-1">入学准备 <a class="header-anchor" href="#入学准备" aria-label="Permalink to &quot;入学准备&quot;">​</a></h1><h2 id="必备" tabindex="-1">必备 <a class="header-anchor" href="#必备" aria-label="Permalink to &quot;必备&quot;">​</a></h2><ul><li><strong>录取通知书</strong></li><li><strong>身份证</strong></li><li><strong>证件照</strong><ul><li>推荐使用小二寸蓝底照片</li><li>尽管大部分情况下对照片背景颜色没有要求，但是你可以各种颜色都备一点</li><li>你也可以保存电子档照片，需要之时再前往校内打印店打印</li></ul></li><li><strong>学籍档案</strong><ul><li>你也可以选择参照新生手册中的步骤邮寄至学校</li></ul></li><li><strong>团员档案</strong>（非团员不用） <ul><li>团员证</li><li>团组织关系介绍信</li><li>团员档案袋</li></ul></li><li><strong>贫困证明材料</strong>（如果需要）</li></ul><h2 id="必要能力" tabindex="-1">必要能力 <a class="header-anchor" href="#必要能力" aria-label="Permalink to &quot;必要能力&quot;">​</a></h2><h3 id="反诈能力" tabindex="-1">反诈能力 <a class="header-anchor" href="#反诈能力" aria-label="Permalink to &quot;反诈能力&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">INFO</p><p>详见<a href="./anti_fraud.html">谨防诈骗</a></p></div><h3 id="独立生活" tabindex="-1">独立生活 <a class="header-anchor" href="#独立生活" aria-label="Permalink to &quot;独立生活&quot;">​</a></h3><p>包括但不限于自己去食堂吃饭、洗衣服、打扫卫生、生病时如何养护自己等</p><p>有的同学可能在初高中阶段均为走读，几乎从未离开家长的怀抱，独立生活能力相对较差，因此在暑假期间务必准备好适应没有家长保驾护航的生活</p><h3 id="最基础的礼貌用语" tabindex="-1">最基础的礼貌用语 <a class="header-anchor" href="#最基础的礼貌用语" aria-label="Permalink to &quot;最基础的礼貌用语&quot;">​</a></h3><p>用好礼貌用语可以避免对方感到不适，同时给人留下更好的第一印象</p><h3 id="查找资料" tabindex="-1">查找资料 <a class="header-anchor" href="#查找资料" aria-label="Permalink to &quot;查找资料&quot;">​</a></h3><p>有时你可能需要找学校发布的官方文件、导员很早之前发过的通知或一些学习资料，但是总是会发现不是找不到就是找的不是想要的</p><h4 id="qq-等聊天软件内" tabindex="-1">QQ 等聊天软件内 <a class="header-anchor" href="#qq-等聊天软件内" aria-label="Permalink to &quot;QQ 等聊天软件内&quot;">​</a></h4><ul><li>直接在首页的搜索栏输入<mark>关键词</mark>查找聊天记录</li><li>看看精华消息、群公告和群文件？说不定导员很早就发过了</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>在向辅导员求助询问前务必按以上方法先查找一遍，可以避免不必要的时间浪费和麻烦</p></div><h4 id="官网通知" tabindex="-1">官网通知 <a class="header-anchor" href="#官网通知" aria-label="Permalink to &quot;官网通知&quot;">​</a></h4><p>推荐使用<a href="https://cn.bing.com/" target="_blank" rel="noreferrer">必应</a>搜索</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>为什么不是<s>百度/搜狗/360 好问</s>等其他搜索引擎</strong></p><ol><li>其他搜索引擎广告非常多</li><li>其他搜索引擎准确度远低于必应</li><li>必应的非中文搜索功能做的更好，这在搜索国外网站时很有帮助</li></ol></div><h3 id="制作-ppt" tabindex="-1">制作 PPT <a class="header-anchor" href="#制作-ppt" aria-label="Permalink to &quot;制作 PPT&quot;">​</a></h3><p>竞选班委、小组作业、答辩时常用到</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>你可以借助<a href="https://www.doubao.com/" target="_blank" rel="noreferrer">豆包</a>、<a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi</a>等 ai 工具</p></div><h2 id="必要物品" tabindex="-1">必要物品 <a class="header-anchor" href="#必要物品" aria-label="Permalink to &quot;必要物品&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>开学前夕快递站常爆满，且校外附近几乎没有驿站，如需邮寄请做好准备</li><li>部分用品可在学校超市购买，不一定需要全部从家里带来</li><li>加粗项为强烈推荐准备的物品</li><li>你可以打印本页后一项一项对照检查</li></ul></div><h3 id="洗护用品" tabindex="-1">洗护用品 <a class="header-anchor" href="#洗护用品" aria-label="Permalink to &quot;洗护用品&quot;">​</a></h3><ul><li><strong>牙刷+牙膏+漱口杯</strong></li><li>报纸 <ul><li>垫床板，买了床垫的同学可以不用这个了</li></ul></li><li>护肤品 <ul><li>女孩子要备好防晒霜哦，军训很辛苦，就别让皮肤再受苦咯</li></ul></li><li><strong>毛巾+浴巾+擦汗巾</strong><ul><li>吸水要好</li><li>在学校买不一定有你喜欢的材质</li></ul></li><li>洗发水+护发素 <ul><li>大瓶划算，也可备一个小瓶，去洗澡间的时候担子轻点</li></ul></li><li>沐浴露/沐浴球/沐浴条</li><li>水杯 <ul><li>两个普通水杯，寝室用、夏季上课用，散热快</li><li>保温杯，冬季可用</li></ul></li><li>水桶 <ul><li>用来放没来得及洗的脏衣服</li></ul></li><li><strong>脸盆</strong><ul><li>选能摞在一起的，节省占地空间</li><li>建议不要买太深的，宿舍架子可能放不进去</li></ul></li><li>暖壶</li><li><strong>抹布 + 小桶 + 扫把套装</strong><ul><li>扫把拖把套装一个寝室买一套就够了</li></ul></li><li>香皂 + 洗手液 + 肥皂盒 <ul><li>肥皂盒可以买两个，一个放香皂，一个放洗衣皂</li></ul></li><li>钢丝球 <ul><li>一个寝室买一个就行啦！进新寝室发现前人不够讲卫生，水池有很多顽渍时可以用</li></ul></li><li>洗衣皂 + 洗洁精 + 洗衣粉</li><li>塑胶手套 <ul><li>冬天手洗衣服还是会有点冻手</li></ul></li><li>衣领净或漂白剂 <ul><li>以备不时之需</li></ul></li><li>刷子 <ul><li>洗鞋用</li></ul></li><li>护手霜+手套+围巾+热水袋 <ul><li>可冬天买</li></ul></li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>去澡间洗澡记得多带几个塑料袋/脸盆/洗衣篮，便于把干衣服、湿衣服、沐浴用品等分开放</p></div><h3 id="宿舍相关用品" tabindex="-1">宿舍相关用品 <a class="header-anchor" href="#宿舍相关用品" aria-label="Permalink to &quot;宿舍相关用品&quot;">​</a></h3><ul><li><strong>衣服</strong><ul><li>四季的外套+各种衣服</li><li>宣城冬季比较冷，准备些厚点衣服比如羽绒服之类的</li></ul></li><li><strong>鞋子</strong><ul><li>帆布鞋+运动鞋+拖鞋凉鞋...</li></ul></li><li>衣架</li><li>晒衣夹</li><li>大夹子 <ul><li>晒被子时候可用</li></ul></li><li>晒衣服的撑杆</li><li>樟脑球 <ul><li>防蛀防霉物品</li></ul></li><li><strong>垃圾篓+塑料袋</strong><ul><li>可以到学校买</li></ul></li><li>发夹，橡皮筋</li><li>镜子</li><li>梳子</li><li>收纳盒</li><li><strong>多用插排</strong></li><li><strong>锁</strong></li><li><strong>台灯</strong><ul><li>能充电的最好</li></ul></li><li>针线包</li><li>胶 <ul><li>液态胶</li><li>固态胶</li><li>502 胶</li><li>大圈透明胶</li><li>双面胶</li></ul></li><li>书架</li><li><strong>指甲剪</strong></li><li>螺丝刀+小锤子+钳子</li><li>剪刀+小刀</li><li>手电筒</li><li>电池</li><li>绳子</li><li>坐垫等</li></ul><h3 id="医药物品" tabindex="-1">医药物品 <a class="header-anchor" href="#医药物品" aria-label="Permalink to &quot;医药物品&quot;">​</a></h3><ul><li>纸卷+纸巾+纸巾筒</li><li>卫生棉</li><li><strong>花露水+风油精+清凉油等</strong><ul><li>驱蚊止痒、治中暑都有用，绝对必备</li></ul></li><li><strong>小型家用药箱</strong><ul><li>校医院不一定都靠得住，而且宣区校医院离南区宿舍较远，有备无患</li><li>可以有这些： <ul><li>白+黑、维 C、三九胃泰、消炎药等</li><li>治感冒、发烧、肠胃问题的药</li><li>有痛经史的女生还要带痛经的药</li><li>消毒水、绷带、棉签、药用绵花、云南白药等以治摔伤、撞伤等意外事故</li></ul></li></ul></li></ul><h3 id="床上用品" tabindex="-1">床上用品 <a class="header-anchor" href="#床上用品" aria-label="Permalink to &quot;床上用品&quot;">​</a></h3><p>宿舍床的尺寸：<strong>1.9m*0.9m</strong></p><ul><li>蚊帐 <ul><li>建议自己带或者定制</li></ul></li><li>枕头+抱枕+枕套</li><li>凉席 <ul><li>学校内超市有卖，质量一般</li></ul></li><li><strong>被子</strong><ul><li>学校有卖全套但质量感人</li><li>冬被、春秋被各一床</li></ul></li><li><strong>被套、床单</strong><ul><li>各两床，搞脏了可换</li></ul></li><li>两个枕套 <ul><li>同上，也要经常换洗</li></ul></li><li>毯子</li></ul><h3 id="军训用品" tabindex="-1">军训用品 <a class="header-anchor" href="#军训用品" aria-label="Permalink to &quot;军训用品&quot;">​</a></h3><ul><li><strong>防晒用品</strong><ul><li><s>厨邦酱油美味鲜，晒足 180 天。你看就在这儿晒。这是宣区军训大晒场，有图有真相，就在这儿晒</s></li></ul></li><li><strong>水壶</strong><ul><li>&gt;1L</li><li>若没有可以去超市买 1.5L 的矿泉水，一般来说男生半天就能喝一桶</li></ul></li><li><strong>质量好点的鞋垫</strong><ul><li>军训时穿迷彩鞋，不垫个好的鞋垫脚会断掉的，即使穿自己的鞋时间长了脚一样会痛</li></ul></li><li><strong>裤带</strong><ul><li>一般来说军训裤子很松，<s>不用裤带的话就等着裤子掉了出名吧</s></li><li>学校内的便利店有卖，但是质量很难评</li></ul></li><li>各种营养品和干粮 <ul><li>芝麻糊，牛奶，泡面，麦片等，军训期间人比较多打饭排队是一件很痛苦的事情</li></ul></li><li><strong>小手帕或者足够足够多的纸巾</strong></li><li>湿纸巾</li><li>凉茶冲剂 <ul><li>消暑</li></ul></li><li>咖啡</li></ul><h3 id="食品相关" tabindex="-1">食品相关 <a class="header-anchor" href="#食品相关" aria-label="Permalink to &quot;食品相关&quot;">​</a></h3><ul><li><strong>家乡特产</strong><ul><li>和舍友打好关系啦~</li></ul></li><li><strong>喝水杯</strong><ul><li>不怕摔的最好</li></ul></li><li>饭盒 <ul><li>泡面用</li></ul></li><li>筷子 <ul><li>泡面用哈</li></ul></li><li><strong>削皮刀、水果刀</strong></li><li><strong>勺子</strong><ul><li>吃西瓜用</li></ul></li><li>榨菜、老干妈、醋、果酱等调味品 <ul><li>油盐酱醋在宿舍属于违禁物品 <ul><li>怕你宿舍开小灶（物理）</li></ul></li></ul></li><li><strong>牛奶、饼干、小面包等开袋即食的东西</strong><ul><li>建议低糖低盐低脂高纤的</li><li>以防半夜饿得想死、以防懒得抽筋不想下楼、以防早上迟到来不及吃早餐</li></ul></li></ul><h3 id="出行小装备" tabindex="-1">出行小装备 <a class="header-anchor" href="#出行小装备" aria-label="Permalink to &quot;出行小装备&quot;">​</a></h3><ul><li>雨伞+遮阳伞 <ul><li>不要光求漂亮，质量要好，不然淋成落汤鸟就不好看了</li></ul></li><li><strong>包</strong><ul><li>大大小小的，自己看着办</li></ul></li><li>钥匙扣 <ul><li>挂宿舍和抽屉钥匙用</li></ul></li><li>家里的钥匙 <ul><li>不然突然想回家了却进不了家门</li></ul></li><li>自行车/电动车 <ul><li>可以考虑</li></ul></li><li>各物件的发票和保修单 <ul><li>如果有全国联保的话</li></ul></li><li><strong>行李箱</strong><ul><li>要求坚不可摧，尺寸你喜欢就好哈哈哈</li></ul></li><li>麻袋 <ul><li>超级实用</li></ul></li></ul><h3 id="文具相关" tabindex="-1">文具相关 <a class="header-anchor" href="#文具相关" aria-label="Permalink to &quot;文具相关&quot;">​</a></h3><ul><li><strong>笔</strong><ul><li>黑色签字笔必备，开学填很多表有用</li><li>高三没用完的笔够用大学四年了</li></ul></li><li><strong>随身带的小记事本</strong><ul><li>很多东西辅导员、老师都只讲一遍，大学的事情远比中学复杂，要记下来才不容易忘</li></ul></li><li><strong>U 盘</strong><ul><li>COPY 老师的课件和交作业等时候要用到</li></ul></li><li><strong>听力耳机</strong><ul><li>非英语专业的同学期末考试要用，所有同学四六级考试都要用</li><li>必须是调频耳机，不要求有蓝牙功能</li></ul></li><li>手表</li><li>订书机</li><li>便利贴</li><li>笔记本</li><li>笔筒</li><li>文件夹</li><li>透明档案袋</li></ul><h3 id="电子产品相关" tabindex="-1">电子产品相关 <a class="header-anchor" href="#电子产品相关" aria-label="Permalink to &quot;电子产品相关&quot;">​</a></h3><ul><li><strong>平板/电脑</strong><ul><li>大学期间有许多任务需要电脑完成，包括但不限于 PPT 制作、视频剪辑、填写资料表格、工图建模</li><li>选工科的同学建议选择 Windows 系统的电脑，否则部分工科软件很难或无法运行</li></ul></li><li><strong>手机充电器或平板充电器，数据线</strong></li><li><strong>护眼台灯</strong></li><li><strong>USB LED 小灯</strong><ul><li>宣区晚上会断电，你可能要补作业或有其他事情需要完成</li></ul></li><li>充电宝</li><li><strong>电吹风</strong><ul><li>功率小一些，不然寝室的功率带不动，大的也可以到洗手间去使用</li><li>洗手间也提供了公用的吹风机，但是需付费使用</li></ul></li><li>数码相机 <ul><li>随时记录大学生活精彩点滴</li><li>参加活动的图像资料以后在交简历、写实践报告的时候附上会很有帮助</li></ul></li><li>散热器</li></ul><p>[^1]: 合肥工业大学本科招生网.2024 级新生入学须知[DB/OL]. (2024-07-29)[2025-08-14].<br><a href="http://bkzs.hfut.edu.cn/static/mobile/front/hfut/basic/html_cms/frontViewArticle.html?id=4969464aa038476a8e2391a43d81981d" target="_blank" rel="noreferrer">http://bkzs.hfut.edu.cn/static/mobile/front/hfut/basic/html_cms/frontViewArticle.html?id=4969464aa038476a8e2391a43d81981d</a></p>',45)])])}const p=i(o,[["render",u]]);export{d as __pageData,p as default};
